{
  "iteration": 10,
  "pcvs": [
    {
      "name": "logit_elements",
      "expression": "logits.numel()",
      "rationale": "Captures batch-wide baseline tensor processing."
    },
    {
      "name": "penalized_logit_elements",
      "expression": "logits.numel() if not sampling_metadata.no_penalties else 0",
      "rationale": "Captures vocabulary-wide penalty processing."
    },
    {
      "name": "retained_topk_elements",
      "expression": "int(sampling_metadata.top_k.sum().item()) if not sampling_metadata.all_greedy and sampling_metadata.top_k is not None else (logits.numel() if not sampling_metadata.all_greedy else 0)",
      "rationale": "Measures the aggregate per-row top-k limits using the small CPU metadata tensor, reflecting how much support remains for subsequent top-p processing."
    },
    {
      "name": "cold_dynamo_sampling",
      "expression": "int(not sampling_metadata.all_greedy and not getattr(getattr(getattr(getattr(torch, '_dynamo', None), 'convert_frame', None), 'output_codes', None), 'seen', {}))",
      "rationale": "Separates the observed initial compilation call."
    }
  ],
  "hypothesis": "The stochastic cost may depend on per-row filtering limits rather than batch size alone. Aggregate top-k support distinguishes heavily filtered random rows from effectively unrestricted rows in mixed batches."
}
